		{"course", "c1", "高等数学", "4"},
		{"req", "s1", "r1", "c1"},
		{"enroll", "s1", "r1", "2024春", "e1"},
		{"pass", "s1", "e1"},
		{"enroll", "s1", "r1", "2024秋", "e2"},
		{"fail", "s1", "e2"},
		{"course-close", "c1"},
	} {
