	// 核对：仍只获得 4 学分，来源仍是原先通过的旧修读 e1；
	// 恢复课程状态本身不代表某次修读通过。
	out, _, code = runCLI(t, file, "check", "s1")
	if code != 0 || !strings.Contains(out, "总学分：4") ||
