	out, _, code = runCLI(t, file, "check", "s1")
	if code != 0 || !strings.Contains(out, "总学分：4") ||
		!strings.Contains(out, "已满足，来源为通过修读 e1") ||
		strings.Contains(out, "共通过 2 次") {
		t.Fatalf("新增选课不应增加学分或改变满足情况，code=%d out=%q", code, out)
	}
