	if code != 0 || !strings.Contains(out, "总学分：0") ||
		!strings.Contains(out, "要求 r1（课程 c1《高等数学》，4 学分）：未满足") ||
		!strings.Contains(out, "未满足要求：[r1]") {
		t.Fatalf("恢复开放后无通过修读的要求应仍未满足、总学分 0，code=%d out=%q", code, out)
	}

	// 恢复后新增选课同样不带来学分：仍 0 学分、未满足。
