		t.Fatalf("旧修读的要求、学期与结果应原样保留，out=%q", out)
	}
	if strings.Contains(out, "修读 e0") {
		t.Fatalf("被拒绝的新修读 e0 不应出现在历史中，out=%q", out)
	}

