		!strings.Contains(out, "要求 r1（课程 c1《高等数学》，4 学分）：已满足，来源为通过修读 e1") ||
		strings.Contains(out, "未满足要求：[") ||
		strings.Contains(out, "共通过 2 次") {
		t.Fatalf("恢复后应仍仅由 e1 满足、计 4 学分，code=%d out=%q", code, out)
	}
}

